# Generated by Duke Forger.
# Imports the rigged + animated blaster trooper (assets/characters/clone_trooper in the Duke repo) into
#   /Game/DukeForge/Characters/<pack>  (SK_Trooper, Anims/A_Trooper_*, SM_Blaster, materials, textures). <pack> comes from
#   Unreal/pack.json: CloneTrooper (Empire), AllyTrooper (Alliance, blue bolts), Jedi (lightsaber blade materials).
#   /Game/DukeForge/FX                        (M_BlasterBolt, M_BlasterBoltGlow used by ADukeBlasterBolt)
#   /Game/DukeForge/Audio                     (S_Blaster_Fire_0x, S_Blaster_Impact)
# Copy the pack's Unreal/ and Audio/ folders to <Project>/Import/characters/clone_trooper/ first (or pass a folder).
# Run headless:
#   UnrealEditor-Cmd.exe <Project>.uproject -run=pythonscript -script="<abs path>/duke_trooper_import.py" -unattended -nosplash
# In the editor's Python console, spawn_test_troopers() drops three patrolling troopers in front of the camera.
import json, os, sys, traceback
import unreal

PROJECT = unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_dir())
SRC = next((a for a in sys.argv[1:] if os.path.isdir(a)), os.path.join(PROJECT, 'Import', 'characters', 'clone_trooper'))
ROOT = '/Game/DukeForge/Characters/CloneTrooper'
PACK = {}
try:   # written by tools/rigging/export.py: which folder this character goes to (CloneTrooper, AllyTrooper, Jedi ...)
    PACK = json.load(open(os.path.join(SRC, 'Unreal', 'pack.json')))
    ROOT = PACK.get('unreal_root', ROOT)
except Exception:
    pass
FX = '/Game/DukeForge/FX'
AUDIO = '/Game/DukeForge/Audio'
EAL = unreal.EditorAssetLibrary
TOOLS = unreal.AssetToolsHelpers.get_asset_tools()
MEL = unreal.MaterialEditingLibrary
REPORT = {'source': SRC, 'imported': [], 'errors': []}

def log(m): unreal.log('[DukeTrooper] ' + m)
def err(m): unreal.log_warning('[DukeTrooper] ' + m); REPORT['errors'].append(m)

try:
    unreal.SystemLibrary.execute_console_command(None, 'Interchange.FeatureFlags.Import.FBX 0')  # classic FBX importer honours FbxImportUI
except Exception:
    pass

def run_import(filename, dest, options=None, name=None):
    t = unreal.AssetImportTask()
    t.set_editor_property('filename', filename)
    t.set_editor_property('destination_path', dest)
    if name: t.set_editor_property('destination_name', name)
    t.set_editor_property('automated', True)
    t.set_editor_property('replace_existing', True)
    t.set_editor_property('save', True)
    if options is not None: t.set_editor_property('options', options)
    TOOLS.import_asset_tasks([t])
    out = list(t.get_editor_property('imported_object_paths') or [])
    REPORT['imported'] += out
    return out

def first(paths, cls):
    for p in paths:
        a = EAL.load_asset(p)
        if isinstance(a, cls): return a
    return None

def fbx_ui(kind, skeleton=None):
    o = unreal.FbxImportUI()
    o.set_editor_property('automated_import_should_detect_type', False)
    o.set_editor_property('import_materials', False)
    o.set_editor_property('import_textures', False)
    if kind == 'static':
        o.set_editor_property('import_as_skeletal', False)
        o.set_editor_property('mesh_type_to_import', unreal.FBXImportType.FBXIT_STATIC_MESH)
        sm = o.get_editor_property('static_mesh_import_data')
        sm.set_editor_property('combine_meshes', True)
        sm.set_editor_property('auto_generate_collision', True)
    elif kind == 'skeletal':
        o.set_editor_property('import_as_skeletal', True)
        o.set_editor_property('mesh_type_to_import', unreal.FBXImportType.FBXIT_SKELETAL_MESH)
        o.set_editor_property('import_animations', False)
        o.set_editor_property('create_physics_asset', True)
        sk = o.get_editor_property('skeletal_mesh_import_data')
        sk.set_editor_property('import_morph_targets', False)
        sk.set_editor_property('normal_import_method', unreal.FBXNormalImportMethod.FBXNIM_IMPORT_NORMALS_AND_TANGENTS)
    else:
        o.set_editor_property('import_as_skeletal', True)
        o.set_editor_property('mesh_type_to_import', unreal.FBXImportType.FBXIT_ANIMATION)
        o.set_editor_property('import_animations', True)
        o.set_editor_property('import_mesh', False)
        o.set_editor_property('skeleton', skeleton)
        ad = o.get_editor_property('anim_sequence_import_data')
        ad.set_editor_property('animation_length', unreal.FBXAnimationLengthImportType.FBXALIT_EXPORTED_TIME)
        ad.set_editor_property('import_bone_tracks', True)
        ad.set_editor_property('remove_redundant_keys', False)
    return o

# ---------- textures ----------
def import_textures():
    folder = os.path.join(SRC, 'Unreal', 'Textures')
    tex = {}
    for f in sorted(os.listdir(folder)):
        if not f.lower().endswith(('.png', '.jpg')): continue
        name = os.path.splitext(f)[0].replace('_OpenGL', '')
        t = first(run_import(os.path.join(folder, f), ROOT + '/Textures', name=name), unreal.Texture2D)
        if not t: err('texture failed: ' + f); continue
        if 'Normal' in name:
            t.set_editor_property('compression_settings', unreal.TextureCompressionSettings.TC_NORMALMAP)
            t.set_editor_property('flip_green_channel', True)   # source is OpenGL (glTF); Unreal is DirectX
            t.set_editor_property('srgb', False)
        elif 'ORM' in name:
            t.set_editor_property('compression_settings', unreal.TextureCompressionSettings.TC_MASKS)
            t.set_editor_property('srgb', False)
        EAL.save_loaded_asset(t)
        tex[name] = t
    return tex

def fresh(path, name, cls, factory):
    full = path + '/' + name
    if EAL.does_asset_exist(full): EAL.delete_asset(full)
    return TOOLS.create_asset(name, path, cls, factory)

def tex_param(m, name, sample_type, x, y):
    e = MEL.create_material_expression(m, unreal.MaterialExpressionTextureSampleParameter2D, x, y)
    e.set_editor_property('parameter_name', name)
    e.set_editor_property('sampler_type', sample_type)
    return e

def master_pbr():
    """M_DukePBR: BaseColor, Normal, ORM (R=AO, G=Roughness, B=Metallic, the glTF packing)."""
    m = fresh(ROOT + '/Materials', 'M_DukePBR', unreal.Material, unreal.MaterialFactoryNew())
    bc = tex_param(m, 'BaseColor', unreal.MaterialSamplerType.SAMPLERTYPE_COLOR, -600, -200)
    nm = tex_param(m, 'Normal', unreal.MaterialSamplerType.SAMPLERTYPE_NORMAL, -600, 100)
    orm = tex_param(m, 'ORM', unreal.MaterialSamplerType.SAMPLERTYPE_MASKS, -600, 400)
    MEL.connect_material_property(bc, 'RGB', unreal.MaterialProperty.MP_BASE_COLOR)
    MEL.connect_material_property(nm, 'RGB', unreal.MaterialProperty.MP_NORMAL)
    MEL.connect_material_property(orm, 'R', unreal.MaterialProperty.MP_AMBIENT_OCCLUSION)
    MEL.connect_material_property(orm, 'G', unreal.MaterialProperty.MP_ROUGHNESS)
    MEL.connect_material_property(orm, 'B', unreal.MaterialProperty.MP_METALLIC)
    m.set_editor_property('used_with_skeletal_mesh', True)
    MEL.recompile_material(m); EAL.save_loaded_asset(m)
    return m

def instance(parent, name, tex, prefix):
    mi = fresh(ROOT + '/Materials', name, unreal.MaterialInstanceConstant, unreal.MaterialInstanceConstantFactoryNew())
    MEL.set_material_instance_parent(mi, parent)
    for p, k in (('BaseColor', 'BaseColor'), ('Normal', 'Normal'), ('ORM', 'ORM')):
        t = tex.get('T_%s_%s' % (prefix, k))
        if t: MEL.set_material_instance_texture_parameter_value(mi, p, t)
        else: err('missing texture T_%s_%s' % (prefix, k))
    EAL.save_loaded_asset(mi)
    return mi

def cap_materials():
    """Cut caps: cauterized (glowing molten rim) for the lightsaber, charred with faint embers for explosions."""
    out = {}
    for key, base, glow, k in (('saber', (0.06, 0.025, 0.015), (1.0, 0.28, 0.05), 6.0), ('blast', (0.04, 0.03, 0.025), (0.9, 0.2, 0.05), 1.0)):
        m = fresh(FX, 'M_CutCap_' + key.capitalize(), unreal.Material, unreal.MaterialFactoryNew())
        b = MEL.create_material_expression(m, unreal.MaterialExpressionConstant3Vector, -500, 0); b.set_editor_property('constant', unreal.LinearColor(*base, 1))
        g = MEL.create_material_expression(m, unreal.MaterialExpressionVectorParameter, -500, 200)
        g.set_editor_property('parameter_name', 'Glow'); g.set_editor_property('default_value', unreal.LinearColor(*glow, 1))
        i = MEL.create_material_expression(m, unreal.MaterialExpressionScalarParameter, -500, 350)
        i.set_editor_property('parameter_name', 'Intensity'); i.set_editor_property('default_value', k)
        mul = MEL.create_material_expression(m, unreal.MaterialExpressionMultiply, -250, 250)
        MEL.connect_material_expressions(g, '', mul, 'A'); MEL.connect_material_expressions(i, '', mul, 'B')
        MEL.connect_material_property(b, '', unreal.MaterialProperty.MP_BASE_COLOR)
        MEL.connect_material_property(mul, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
        m.set_editor_property('used_with_skeletal_mesh', True)
        MEL.recompile_material(m); EAL.save_loaded_asset(m); out[key] = m
    return out

def bolt_materials():
    """Emissive red bolt core (unlit) and a soft additive glow shell; colour is a parameter."""
    core = fresh(FX, 'M_BlasterBolt', unreal.Material, unreal.MaterialFactoryNew())
    core.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
    c = MEL.create_material_expression(core, unreal.MaterialExpressionVectorParameter, -500, 0)
    c.set_editor_property('parameter_name', 'Color'); c.set_editor_property('default_value', unreal.LinearColor(1, 0.06, 0.04, 1))
    i = MEL.create_material_expression(core, unreal.MaterialExpressionScalarParameter, -500, 200)
    i.set_editor_property('parameter_name', 'Intensity'); i.set_editor_property('default_value', 40.0)
    # white-hot centre: lerp colour toward white
    white = MEL.create_material_expression(core, unreal.MaterialExpressionConstant3Vector, -500, -150)
    white.set_editor_property('constant', unreal.LinearColor(1, 0.85, 0.8, 1))
    lp = MEL.create_material_expression(core, unreal.MaterialExpressionLinearInterpolate, -250, 0)
    lp.set_editor_property('const_alpha', 0.35)
    MEL.connect_material_expressions(c, '', lp, 'A'); MEL.connect_material_expressions(white, '', lp, 'B')
    mul = MEL.create_material_expression(core, unreal.MaterialExpressionMultiply, -100, 0)
    MEL.connect_material_expressions(lp, '', mul, 'A'); MEL.connect_material_expressions(i, '', mul, 'B')
    MEL.connect_material_property(mul, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    MEL.recompile_material(core); EAL.save_loaded_asset(core)

    glow = fresh(FX, 'M_BlasterBoltGlow', unreal.Material, unreal.MaterialFactoryNew())
    glow.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
    glow.set_editor_property('blend_mode', unreal.BlendMode.BLEND_ADDITIVE)
    c2 = MEL.create_material_expression(glow, unreal.MaterialExpressionVectorParameter, -600, 0)
    c2.set_editor_property('parameter_name', 'Color'); c2.set_editor_property('default_value', unreal.LinearColor(1, 0.06, 0.04, 1))
    i2 = MEL.create_material_expression(glow, unreal.MaterialExpressionScalarParameter, -600, 200)
    i2.set_editor_property('parameter_name', 'Intensity'); i2.set_editor_property('default_value', 10.0)
    fr = MEL.create_material_expression(glow, unreal.MaterialExpressionFresnel, -600, 350)
    inv = MEL.create_material_expression(glow, unreal.MaterialExpressionOneMinus, -400, 350)
    MEL.connect_material_expressions(fr, '', inv, '')
    m1 = MEL.create_material_expression(glow, unreal.MaterialExpressionMultiply, -300, 0)
    MEL.connect_material_expressions(c2, '', m1, 'A'); MEL.connect_material_expressions(i2, '', m1, 'B')
    m2 = MEL.create_material_expression(glow, unreal.MaterialExpressionMultiply, -150, 100)
    MEL.connect_material_expressions(m1, '', m2, 'A'); MEL.connect_material_expressions(inv, '', m2, 'B')
    MEL.connect_material_property(m2, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    MEL.recompile_material(glow); EAL.save_loaded_asset(glow)

def saber_materials():
    # lightsaber blade: unlit emissive core (near white) and a coloured glow shell (translucent, additive)
    col = PACK.get('blade_color') or [0.1, 0.45, 1.0]
    out = {}
    for key, c, k, blend in (('Core', [0.8, 0.9, 1.0], 18.0, unreal.BlendMode.BLEND_OPAQUE), ('Glow', col, 9.0, unreal.BlendMode.BLEND_ADDITIVE)):
        m = fresh(ROOT + '/Materials', 'M_SaberBlade_' + key, unreal.Material, unreal.MaterialFactoryNew())
        m.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
        m.set_editor_property('blend_mode', blend)
        v = MEL.create_material_expression(m, unreal.MaterialExpressionVectorParameter, -500, 0)
        v.set_editor_property('parameter_name', 'Color'); v.set_editor_property('default_value', unreal.LinearColor(c[0], c[1], c[2], 1))
        i = MEL.create_material_expression(m, unreal.MaterialExpressionScalarParameter, -500, 200)
        i.set_editor_property('parameter_name', 'Intensity'); i.set_editor_property('default_value', k)
        mul = MEL.create_material_expression(m, unreal.MaterialExpressionMultiply, -250, 100)
        MEL.connect_material_expressions(v, '', mul, 'A'); MEL.connect_material_expressions(i, '', mul, 'B')
        MEL.connect_material_property(mul, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
        MEL.recompile_material(m); EAL.save_loaded_asset(m); out[key] = m
    return out

def import_audio():
    folder = os.path.join(SRC, 'Audio')
    if not os.path.isdir(folder): err('no Audio folder'); return
    for f in sorted(os.listdir(folder)):
        if f.lower().endswith('.wav'):
            paths = run_import(os.path.join(folder, f), AUDIO)
            if f.startswith('S_Saber_Hum'):   # the lightsaber hum plays as a constant loop while the blade is lit
                w = first(paths, unreal.SoundWave)
                if w: w.set_editor_property('looping', True); EAL.save_loaded_asset(w)

def main():
    log('source ' + SRC)
    tex = import_textures()
    pbr = master_pbr()
    mi_trooper = instance(pbr, 'MI_Trooper', tex, 'Trooper')
    mi_blaster = instance(pbr, 'MI_Blaster', tex, 'Blaster')
    saber = saber_materials() if PACK.get('weapon_kind') == 'saber' else {}
    def pick(slot):
        if saber and 'SaberBlade_Core' in slot: return saber['Core']
        if saber and 'SaberBlade_Glow' in slot: return saber['Glow']
        return mi_blaster if 'Blaster' in slot else mi_trooper
    bolt_materials()
    import_audio()

    paths = run_import(os.path.join(SRC, 'Unreal', 'SK_Trooper.fbx'), ROOT, fbx_ui('skeletal'), name='SK_Trooper')
    sk = first(paths, unreal.SkeletalMesh)
    if not sk: err('SK_Trooper did not import'); return
    skeleton = sk.get_editor_property('skeleton')
    mats = sk.get_editor_property('materials')
    for i, sm in enumerate(mats):
        slot = str(sm.get_editor_property('material_slot_name'))
        sm.set_editor_property('material_interface', pick(slot))
        mats[i] = sm
    sk.set_editor_property('materials', mats)
    # weapon_r (grip) and muzzle (bolt spawn) are real bones, usable directly as sockets.
    EAL.save_loaded_asset(sk)
    log('SK_Trooper imported')

    ROOT_MOTION_CLIPS = {'A_Trooper_' + c for c in ('roll_to_kneel', 'mantle', 'vault', 'turn_l90', 'turn_r90', 'turn_l180', 'turn_r180', 'run_stop', 'dive_left', 'dive_right', 'breach_clear')}
    anim_dir = os.path.join(SRC, 'Unreal', 'Animations')
    n = 0
    for f in sorted(os.listdir(anim_dir)):
        if not f.endswith('.fbx'): continue
        name = os.path.splitext(f)[0]
        seq = first(run_import(os.path.join(anim_dir, f), ROOT + '/Anims', fbx_ui('anim', skeleton), name=name), unreal.AnimSequence)
        if not seq: err('animation failed: ' + f); continue
        # clips that travel or turn the root: the root is locked in the pose so the mesh stays on the capsule
        # (DukeTrooper moves/turns the capsule itself for roll, mantle, vault and the 90-degree turns)
        seq.set_editor_property('enable_root_motion', name in ROOT_MOTION_CLIPS)
        EAL.save_loaded_asset(seq); n += 1
    log('%d animations imported' % n)

    # dismemberment variants (lightsaber endings, explosion limb loss): same skeleton, swapped in at the cut
    cut_dir = os.path.join(SRC, 'Unreal', 'Cuts')
    if os.path.isdir(cut_dir):
        caps = cap_materials()
        for f in sorted(os.listdir(cut_dir)):
            if not f.endswith('.fbx'): continue
            name = os.path.splitext(f)[0]
            ui = fbx_ui('skeletal'); ui.set_editor_property('skeleton', skeleton); ui.set_editor_property('create_physics_asset', False)
            cm = first(run_import(os.path.join(cut_dir, f), ROOT + '/Cuts', ui, name=name), unreal.SkeletalMesh)
            if not cm: err('cut variant failed: ' + f); continue
            ms = cm.get_editor_property('materials')
            for i, sm in enumerate(ms):
                slot = str(sm.get_editor_property('material_slot_name'))
                mat = caps['saber'] if 'CutCap_Saber' in slot else caps['blast'] if 'CutCap_Blast' in slot else pick(slot)
                sm.set_editor_property('material_interface', mat); ms[i] = sm
            cm.set_editor_property('materials', ms); EAL.save_loaded_asset(cm)
        log('cut variants imported')
    run_import(os.path.join(SRC, 'Unreal', 'SM_Blaster.fbx'), ROOT, fbx_ui('static'), name='SM_Blaster')
    bl = EAL.load_asset(ROOT + '/SM_Blaster')
    if bl:
        bl.set_material(0, mi_blaster); EAL.save_loaded_asset(bl)
    EAL.save_directory('/Game/DukeForge')
    REPORT['animations'] = n

def spawn_test_troopers(count=3):
    """Editor helper: place troopers 6 m in front of the viewport camera, each with a square patrol route."""
    cls = unreal.load_class(None, '/Script/DukeGame.DukeTrooper')
    if not cls: err('DukeTrooper class not found (compile the C++ module first)'); return []
    loc, rot = unreal.EditorLevelLibrary.get_level_viewport_camera_info()
    fwd = rot.get_forward_vector(); right = rot.get_right_vector()
    out = []
    for i in range(count):
        p = loc + fwd * 600.0 + right * ((i - (count - 1) / 2.0) * 250.0)
        p.z = loc.z - 100.0
        a = unreal.EditorLevelLibrary.spawn_actor_from_class(cls, p, unreal.Rotator(0, rot.yaw + 180.0, 0))
        a.set_editor_property('patrol_points', [unreal.Vector(0, 0, 0), unreal.Vector(500, 0, 0), unreal.Vector(500, 500, 0), unreal.Vector(0, 500, 0)])
        out.append(a)
    return out

if __name__ == '__main__':
    try:
        main()
    except Exception:
        err(traceback.format_exc())
    os.makedirs(os.path.join(PROJECT, 'Saved', 'DukeForge'), exist_ok=True)
    with open(os.path.join(PROJECT, 'Saved', 'DukeForge', 'trooper_import.json'), 'w') as fh:
        json.dump(REPORT, fh, indent=1)
    log('done, %d errors' % len(REPORT['errors']))
